SELECT 
FROM TC_DATA_SOURCE_CONFIG
WHERE STATUS = '1'

    AND SOURCE_CODE LIKE CONCAT('%', #{sourceCode,jdbcType=VARCHAR}, '%')


    AND SOURCE_NAME LIKE CONCAT('%', #{sourceName,jdbcType=VARCHAR}, '%')


    AND SOURCE_TYPE = #{sourceType,jdbcType=VARCHAR}


    AND DATA_TYPE = #{dataType,jdbcType=VARCHAR}


    AND SYNC_STATUS = #{syncStatus,jdbcType=VARCHAR}


    AND IS_ACTIVE = #{isActive,jdbcType=VARCHAR}


    AND STATUS = #{status,jdbcType=VARCHAR}

ORDER BY CREATE_TIME DESC

